INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱元璋", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "status": "draft", "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "李善长", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1353年受朱元璋留为幕书记。", "biography": null, "status": "draft", "id": "fcb986aa-d440-5732-984a-f4c744f5a06d"}, {"name": "常遇春", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "怀远人，1355年投朱元璋、采石先登。", "biography": null, "status": "draft", "id": "51d50a75-07e1-574f-b22d-1fded66288ff"}, {"name": "赵庸（吴水军将）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "与俞通海等六舟穿阵。", "biography": null, "status": "draft", "id": "4c2cba82-98a7-51f5-9ec7-0b233bc05f74"}, {"name": "杨宪（朱元璋儒士）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1356年朱元璋录用的儒士，奉使张士诚而被扣留；与旧南宋使金副使杨宪分开。", "biography": null, "status": "draft", "id": "0b8375cf-8092-5291-8774-008709bac291"}, {"name": "徐达", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "濠州人，1353年随朱元璋南略。", "biography": null, "status": "draft", "id": "0f28446e-78b0-5db1-9677-98777005803e"}, {"name": "胡廷瑞", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "陈友谅江西丞相，降吴，康泰舅。", "biography": null, "status": "draft", "id": "802e1135-35a4-5a18-8000-e933e784a608"}, {"name": "傅瓛", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "1362年随朱元璋自洪都返建康。", "biography": null, "status": "draft", "id": "67a47e8c-13fe-56bb-942b-3109c0b965ea"}, {"name": "廖永忠", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "吴水军将，1361年破安庆水寨。", "biography": null, "status": "draft", "id": "ccd9ff8d-290a-5c16-b1c7-90eeb0f8d3ee"}, {"name": "汪广洋", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年任朱元璋帅府令史。", "biography": null, "status": "draft", "id": "ac800e6b-ef48-5dc3-964b-d67d64245b02"}, {"name": "李伯升", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "与张士诚兄弟同起的十八人之一。", "biography": null, "status": "draft", "id": "8abdb997-f610-51ef-8204-4689bd7d2809"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱元璋建明称帝，立马后、太子标", "description": "朱元璋在南郊祭天地，即皇帝位，定国号明，年号洪武，追尊四代父祖及其配偶，立马氏为皇后、世子标为皇太子，以李善长为左丞相、徐达为右丞相。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "99e92a05-e27c-5dad-a52b-e51faec247ac"}, {"title": "朱元璋设朝臣兼任东宫官，不采用元太子中书令制", "description": "周宗请求重视教导太子，获准。中书省、都督府请仿元制，以太子为中书令，朱元璋拒绝，命詹同考察历代制度，由李善长、徐达、常遇春等兼任东宫官，以免另设府僚后发生嫌隙。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f470c02c-e216-5c59-a88b-e84faa1d2611"}, {"title": "杨宪署理汴梁省务", "description": "洪武元年（1368年）五月，参知政事杨宪在汴梁署理省务。", "start_year": 1368, "end_year": 1368, "time_original": "洪武元年五月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "4b2669bf-858a-57b7-aaf8-67f04c561e0b"}, {"title": "傅瓛被免去参知政事", "description": "洪武元年（1368年）八月，傅瓛被免去参知政事职务。", "start_year": 1368, "end_year": 1368, "time_original": "洪武元年八月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "c8ae5bba-bf34-59a4-be24-be556f924e59"}, {"title": "汪广洋任参知政事", "description": "洪武元年（1368年）十二月，汪广洋任中书省参知政事。", "start_year": 1368, "end_year": 1368, "time_original": "洪武元年十二月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "ecdd557b-3342-5a81-89ad-4f77924549d9"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

